<?php
require_once __DIR__ . '/../config/security.php';
start_secure_session();
require_once __DIR__ . '/../config/database.php';
require_portal_role($conn, 'dentist', false);
 start_secure_session();require_once '../config/database.php';if(($_SESSION['role']??'')!=='dentist'){header('Location: ../auth/login.php');exit;}$from=$_GET['from']??'';$to=$_GET['to']??'';$type=$_GET['type']??'appointments';$rows=[];$sql='';if($type==='appointments')$sql="SELECT a.appointment_date date,CONCAT(u.first_name,' ',u.last_name) patient,a.appointment_type item,a.status FROM appointments a JOIN users u ON u.id=a.patient_id";elseif($type==='treatments')$sql="SELECT tp.created_at date,CONCAT(u.first_name,' ',u.last_name) patient,tp.procedure_name item,tp.status FROM treatment_plans tp JOIN users u ON u.id=tp.patient_id";elseif($type==='laboratory')$sql="SELECT lc.request_date date,CONCAT(u.first_name,' ',u.last_name) patient,CONCAT(lc.case_type,' / ',lc.laboratory_name) item,lc.status FROM laboratory_cases lc JOIN users u ON u.id=lc.patient_id";else $sql="SELECT d.record_date date,CONCAT(u.first_name,' ',u.last_name) patient,d.procedure_name item,COALESCE(d.diagnosis,'') status FROM dental_records d JOIN users u ON u.id=d.patient_id";$conds=[];if($from)$conds[]="date >= '".$conn->real_escape_string($from)."'";if($to)$conds[]="date <= '".$conn->real_escape_string($to)."'";if($conds)$sql.=' WHERE '.implode(' AND ',$conds);$sql.=' ORDER BY date DESC';$res=$conn->query($sql);if($res)$rows=$res->fetch_all(MYSQLI_ASSOC);require '../includes/ui.php';ui_header('Reports','dentist');ui_sidebar('dentist','reports.php');?><div class="page-head"><div><div class="eyebrow">REPORTS</div><h1>Clinic Reports</h1><div class="muted">Generate reports from real system records.</div></div><button class="btn btn-secondary" onclick="window.print()">Print</button></div><section class="card"><form class="searchbar"><select name="type"><option value="appointments" <?=$type==='appointments'?'selected':''?>>Appointments</option><option value="treatments" <?=$type==='treatments'?'selected':''?>>Treatments</option><option value="laboratory" <?=$type==='laboratory'?'selected':''?>>Laboratory</option><option value="history" <?=$type==='history'?'selected':''?>>Dental Records</option></select><input type="date" name="from" value="<?=e($from)?>"><input type="date" name="to" value="<?=e($to)?>"><button class="btn btn-primary">Generate</button></form><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Patient</th><th>Item</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(date('M d, Y',strtotime($r['date'])))?></td><td><?=e($r['patient'])?></td><td><?=e($r['item'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="4" class="empty">No records found for the selected filters.</td></tr><?php endif;?></tbody></table></div></section><?php ui_footer();?>
